from pathlib import Path
import re,html,difflib,markdown,json
O=Path(__file__).resolve().parent;R=O.parents[3]
def render(s):return markdown.markdown(re.sub(r'<!--\s*@[^>]*-->','',s),extensions=['extra','sane_lists'])
def image(n,c):return '<figure><a href="'+n+'.png"><img loading="lazy" src="'+n+'.png" alt="'+html.escape(c,quote=True)+'"></a><figcaption>'+c+'</figcaption></figure>'
before=(O/'Color_Grid_Pallet.before.md').read_text(encoding='utf-8');after=(R/'commons/maps/Color_Grid_Pallet/final.md').read_text(encoding='utf-8');assert after==(O/'Color_Grid_Pallet.after.md').read_text(encoding='utf-8')
a=before.split('\n\n');b=after.split('\n\n');pairs=[]
for tag,i,j,k,l in difflib.SequenceMatcher(None,a,b,autojunk=False).get_opcodes():
 if tag=='equal':continue
 pairs.append('<div class="pair"><div><h3>Before</h3>'+(render('\n\n'.join(a[i:j])) or '<p>Added shared illustration.</p>')+'</div><div><h3>Now</h3>'+render('\n\n'.join(b[k:l]))+'</div></div>')
css=re.search(r'<style>(.*?)</style>',(O.parent/'2026-09-23-array-molnar-volume/index.html').read_text(encoding='utf-8'),re.S)[1]
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Grid — an address keeps a colour</title><style>'+css+'</style></head><body><main>'
page+='''<div class="eyebrow">Ada Research · Colour · 23 September 2026</div><h1>An address keeps a colour.</h1><p class="intro">The outline has travelled.<br>Your exception has not followed it.</p><p class="status">Applied to <strong>Color_Grid_Pallet/final.md</strong>. Two small prose revisions and a shared native four-state illustration. The existing room and address lesson remain.</p><nav><a href="#encounter">Leave and return</a><a href="#floor">The same floor</a><a href="#comparison">What changed</a><a href="#reading">Read the chapter</a><a href="#evidence">Evidence</a><a href="/compose/sources?map=Color_Grid_Pallet&amp;doc=final">Read and comment</a></nav>'''
page+='<section id="encounter"><h2>Something stays when attention moves</h2>'+image('an-address-keeps-colour','Four states of the actual museum floor, from one camera. The pink value stays at (10,10) as the white outline leaves and returns. RULE writes the original colour again. In the last frame, the ordinary museum walker is standing on that same square.')+'<p>The encounter already makes a useful distinction between selection and storage. Looking at another address does not carry the previous value there. Replacing it requires another write.</p>'+image('readout-edited','The existing console reads the actual stored colour at (10,10). The small swatch and the floor receive that value under different viewing conditions.')+'</section>'
page+='<section id="floor"><h2>Rewriting colour leaves support in place</h2>'+image('console-and-floor','The existing console, floor, spectrum forest and secondary works. No new control or replacement substrate was added.')+'<p>The walker can leave the console, reach the pink square, remain supported through RULE, and return. The visible regularity can be reinstated without changing the floor’s geometry. That is the particular event the chapter asks the reader to consider.</p><details><summary>Another palette; the same assignment</summary>'+image('another-palette','PALETTE supplies a different collection to the same coordinate-sum rule. Cube transforms and collision remain in place.')+'</details></section>'
page+='<section id="comparison"><h2>Keep the question on the floor</h2><p>The permissions paragraph now follows a square the program can recolour but the console will not let the visitor select. The phrase “history stack” becomes the concrete statement that each address keeps only its current colour. Future encounters remain in the critical companion. Both code excerpts, the stored-value explanation, the diagonal comparison and the painting handoff are preserved.</p>'+''.join(pairs)+'<p><a href="Color_Grid_Pallet.diff">Exact manuscript diff</a> · <a href="source-changes.diff">Companion changes</a></p></section>'
page+='<section id="reading"><article class="reading">'+render(after)+'</article></section>'
page+='''<section id="evidence" class="evidence"><h2>What was checked</h2><p>36 focused assertions pass in the isolated production museum. Supplied pointer press/release events operate the actual five buttons. COLOUR changes exactly one instance. Both coordinate cycles return to the stored exception. RULE replaces it; equal sums agree; PALETTE applies the same rule to all mapped floor cells, including addresses beyond the manual region. The swatch/readout agree with the stored value.</p><p>Supplied key input drives the ordinary controller beside the plinth, onto the edited square, and back. Floor support is retained through the rewrite. Every instance transform remains unchanged; the starting palette and ink index are restored before the isolated run ends.</p><p>An extra parenthesis in the newly authored probe was corrected before the successful run. No production repair was needed. Native and composed images were inspected; the four-state figure uses one camera, with the walker present in the last frame. No generated illustration stands in for the museum.</p><p>No source, map, geometry, controls or primary selection changed. No tracked-controller reach, headset comfort, colour-calibration, learner or performance claim; no live restart, live bake/save overwrite, commit or frozen book/audio rebuild.</p><p><a href="report.json">Runtime record</a> · <a href="source_manifest.json">Capture inputs</a> · <a href="verification.json">Preservation and publication checks</a> · <a href="SUMMARY.md">Findings and decisions</a></p></section><footer>Next: Color_Paint — a surface on which moving bodies leave marks.</footer></main></body></html>'''
(O/'index.html').write_text(page,encoding='utf-8')
diffs=[]
for rel in json.loads((O/'baseline-hashes.json').read_text()):
 if rel.endswith('/final.md'):continue
 diffs.extend(difflib.unified_diff((O/'before'/rel).read_text(encoding='utf-8').splitlines(True),(R/rel).read_text(encoding='utf-8').splitlines(True),fromfile='before/'+rel,tofile=rel))
(O/'source-changes.diff').write_text(''.join(diffs),encoding='utf-8')
print('Built current reading, native comparisons and exact changes.')
